import numpy as np
from scipy.ndimage import gaussian_filter1d

def contours(m,smooth=1.4):
 m=np.pad(np.asarray(m,bool),1)
 edges=[]
 for y,x in zip(*np.where(m)):
  if not m[y-1,x]:edges.append(((x-1,y-1),(x,y-1)))
  if not m[y,x+1]:edges.append(((x,y-1),(x,y)))
  if not m[y+1,x]:edges.append(((x,y),(x-1,y)))
  if not m[y,x-1]:edges.append(((x-1,y),(x-1,y-1)))
 links={}
 for a,b in edges:links.setdefault(a,[]).append(b)
 paths=[]
 while links:
  start=next(iter(links));a=start;path=[a]
  while a in links:
   b=links[a].pop()
   if not links[a]:del links[a]
   path.append(b);a=b
   if a==start:break
  if len(path)>8:
   p=np.array(path[:-1],float)-.5
   if smooth:p=gaussian_filter1d(p,smooth,axis=0,mode='wrap')
   paths.append(np.vstack([p,p[0]]))
 return sorted(paths,key=len,reverse=True)
